window.examBySubject={};
function configurePracticeSubject(){if(typeof exam==='undefined'||exam.subject===currentSubject)return;window.cleanupExam?.();examBySubject[exam.subject||'termicas']=exam;const previous=exam;exam=examBySubject[currentSubject]||{...previous,subject:currentSubject,history:[],messages:[],started:false,finished:false,busy:false,unit:-1,planToken:null,planProgress:null,includeVisual:false,error:'',recording:false,blob:null,blobURL:null,draft:'',seconds:0};examTopics=currentSubject==='termicas'?[...thermalExamTopics]:[...coursePractice[currentSubject].topics];learningTopics=currentSubject==='termicas'?[...thermalLearningTopics]:[...coursePractice[currentSubject].topics];maqAccount.progress=null;if(maqAccount.user)loadSubjectProgress()}
async function loadSubjectProgress(){const subject=currentSubject,user=maqAccount.user?.id;if(!user)return;try{const p=await accountAPI('/api/progress?subject='+encodeURIComponent(subject));if(subject!==currentSubject||maqAccount.user?.id!==user)return;maqAccount.progress=p;refreshProgressUI();if(location.hash==='#progreso')renderProgressPage()}catch(e){if(subject===currentSubject){maqAccount.error=e.message;refreshProgressUI()}}}
function studyQuestionLabel(id){const card=coursePractice[currentSubject]?.cards.find(c=>c.id===id);if(card)return card.question;if(id.startsWith('visual-'))return 'Lámina '+id.slice(7).replaceAll('-',' ');const match=id.match(/-q(\d+)$/);return match?'Pregunta '+(Number(match[1])+1):id}
function examSourceURL(r){if(r.url)return r.url;if(r.id.startsWith('BII-'))return 'https://drive.google.com/file/d/1eK0ar8DqgNc-jdxkMpxSqck99HfkB_DU/view#page='+r.id.split('-')[1];if(r.id.startsWith('BI-'))return sources.book+'#page='+r.id.split('-')[1];if(r.id.startsWith('turbinas-'))return 'https://docs.google.com/document/d/12jYZ1yKDaT50KlPs9JprAmgbbh_D7ZuN/edit';return r.id.startsWith('clase-')?sources.class:sources.program}
function renderSubjectTopics(){const config=coursePractice[currentSubject];if(!config)return;document.querySelector('#topics').innerHTML=config.topics.map((name,i)=>`<button data-study-topic="${i}"><small>${String(i+1).padStart(2,'0')}</small> ${esc(name)}</button>`).join('');document.querySelectorAll('[data-study-topic]').forEach(b=>b.onclick=()=>{window.subjectReviewTopic=+b.dataset.studyTopic;location.hash='oral';render()})}
function subjectTopicCards(){const c=coursePractice[currentSubject];if(!c)return '';return `<section class="subject-topic-section"><div class="section-head"><h2>${c.basis==='programa'?'Unidades del programa leído':'Temas de práctica según los materiales'}</h2></div><p class="source">${c.basis==='programa'?'Los títulos sintetizan las unidades del documento de la materia.':'Esta organización sirve para estudiar los apuntes disponibles; no se presenta como programa oficial completo.'}</p><div class="grid">${c.topics.map((t,i)=>`<article class="card"><span class="eyebrow">TEMA ${i+1}</span><h3>${esc(t)}</h3><p>${c.cards.filter(q=>q.topic===i).length} preguntas preparadas.</p></article>`).join('')}</div></section>`}
function renderSubjectReview(){const subject=currentSubject,config=coursePractice[subject];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#oral'));let topic=Number.isInteger(window.subjectReviewTopic)&&subjectReviewTopic<config.topics.length?subjectReviewTopic:-1;const cards=config.cards.filter(c=>topic===-1||c.topic===topic);const positionKey='review-position-'+topic;let pos=Number(saved.answers[positionKey])||0;if(pos>=cards.length)pos=0;const card=cards[pos];app.innerHTML=head('REPASO · '+config.name,'Explicalo con tus palabras.','Respondé, dibujá si hace falta y compará con la referencia. Para una nota y seguimiento guardado, usá el profesor IA.')+`<section class="oral-card"><div class="card-top"><select id="subject-review-topic" aria-label="Tema de repaso"><option value="-1">Todos los temas</option>${config.topics.map((t,i)=>`<option value="${i}">${i+1}. ${esc(t)}</option>`).join('')}</select><span>${pos+1} / ${cards.length}</span></div><p class="eyebrow">${esc(config.topics[card.topic])}</p><h2>${esc(card.question)}</h2>${card.visual?renderVisualExercise({visual:card.visual}):''}<textarea id="subject-review-response" aria-label="Tu respuesta de repaso" placeholder="Ordená tu explicación…">${esc(saved.answers[card.id]||'')}</textarea><div class="actions"><button id="subject-review-reveal" class="secondary">Ver respuesta de referencia</button><button id="subject-review-next" class="secondary">Otra pregunta →</button><a class="button" href="#profesor">Evaluar con el profesor</a></div><div id="subject-review-answer" class="answer" hidden></div><p class="source">La referencia es una guía didáctica, no una transcripción literal ni una calificación oficial.</p></section>`;const select=document.querySelector('#subject-review-topic');select.value=topic;select.onchange=e=>{subjectReviewTopic=+e.target.value;renderSubjectReview()};document.querySelector('#subject-review-response').oninput=e=>{saved.answers[card.id]=e.target.value;persist()};document.querySelector('#subject-review-next').onclick=()=>{saved.answers[positionKey]=(pos+1)%cards.length;persist();renderSubjectReview()};document.querySelector('#subject-review-reveal').onclick=async()=>{const button=document.querySelector('#subject-review-reveal');button.disabled=true;const target=document.querySelector('#subject-review-answer');target.hidden=false;target.textContent='Cargando referencia…';try{const d=await accountAPI('/api/study',{subject,id:card.id});if(subject!==currentSubject||!document.querySelector('#subject-review-answer'))return;target.innerHTML='<p>'+esc(d.answer)+'</p>'+(d.sources||[]).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a>`).join('<br>')}catch(e){if(subject===currentSubject)target.textContent=e.message}finally{button.disabled=false}}}
